companies = list_companies({})
first = boundary retry 2 {
    return list_contacts({ page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 { return list_contacts({ page }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
contacts = fold acc = first.items for page in remaining { return acc + page }

domain_to_company = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

is_valid_e164 = regex.test

results = for contact in contacts {
    email = contact.email if contact.email != null else ""
    parts = text.split(email, "@")
    domain = text.lower(parts[1]) if list.length(parts) == 2 else ""
    need_company = (contact.company == null or contact.company == "") and domain != "" and domain in domain_to_company
    new_company = domain_to_company[domain] if need_company else null

    phone = contact.phone if contact.phone != null else ""
    phone_valid = regex.test(phone, "^\\+1[0-9]{10}$")
    digits_only = regex.replace(phone, "[^0-9]", "")
    normalized = if text.starts_with(digits_only, "1") and text.length(digits_only) == 11 {
        return "+" + digits_only
    } else if text.length(digits_only) == 10 {
        return "+1" + digits_only
    } else {
        return phone
    }
    need_phone = phone != "" and (not phone_valid) and regex.test(normalized, "^\\+1[0-9]{10}$")
    new_phone = normalized if need_phone else null

    updated = false
    if need_company or need_phone {
        u = boundary retry 2 {
            return update_contact({
                id: contact.id,
                company: new_company if need_company else null,
                phone: new_phone if need_phone else null
            })
        } catch err {
            return fail("UPDATE_FAILED", err.code + ": " + err.message)
        }
        updated = true
    }
    return {
        phone_fixed: need_phone,
        company_filled: need_company
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, submit }

